do $m$
declare src text; n text;
begin
  -- Mines
  src := pg_get_functiondef('public.rd_mines_mult'::regproc);
  n := replace(src, 'declare x float8 := 0.98;', 'declare x float8 := 0.97;');
  if n = src then raise exception 'rd_mines_mult: trecho nao encontrado'; end if; execute n;
  -- Spill e Pump
  src := pg_get_functiondef('public.rd_spill_mult'::regproc);
  n := replace(src, 'return floor(0.98 / s * 100) / 100;', 'return floor(0.97 / s * 100) / 100;');
  if n = src then raise exception 'rd_spill_mult: trecho nao encontrado'; end if; execute n;
  -- Wheel (baixo e alto) e Coinflip
  src := pg_get_functiondef('public.play_bet'::regproc);
  n := replace(src, 'array[1.4, 1.2, 1.2, 1.2, 0, 1.2, 1.2, 1.2, 1.2, 0]::float8[]', 'array[1.37, 1.19, 1.19, 1.19, 0, 1.19, 1.19, 1.19, 1.19, 0]::float8[]');
  if n = src then raise exception 'play_bet: wheel baixo nao encontrado'; end if; src := n;
  n := replace(src, 'floor(0.98::float8 * v_n * 100 + 0.5) / 100', 'floor(0.97::float8 * v_n * 100 + 0.5) / 100');
  if n = src then raise exception 'play_bet: wheel alto nao encontrado'; end if; src := n;
  n := replace(src, 'floor(0.98::float8 * power(2::float8, v_n) * 100) / 100', 'floor(0.97::float8 * power(2::float8, v_n) * 100) / 100');
  if n = src then raise exception 'play_bet: coinflip nao encontrado'; end if; execute n;
  -- Cross the Lake: rodadas novas comecam em 0,97
  src := pg_get_functiondef('public.round_start'::regproc);
  n := replace(src, $q$'steps', 0, 'mult', 0.98, 'path'$q$, $q$'steps', 0, 'mult', 0.97, 'path'$q$);
  if n = src then raise exception 'round_start: lake nao encontrado'; end if; execute n;
  -- Hi-Lo e Pedra-papel-tesoura (o Crash desta funcao nao muda)
  src := pg_get_functiondef('public.round_act'::regproc);
  n := replace(src, 'v_mult := floor(v_mult * (0.98 / v_p) * 100) / 100;', 'v_mult := floor(v_mult * (0.97 / v_p) * 100) / 100;');
  if n = src then raise exception 'round_act: hilo nao encontrado'; end if; src := n;
  n := replace(src, 'floor(0.98 * power(2::float8, v_wins) * 100 + 0.5) / 100', 'floor(0.97 * power(2::float8, v_wins) * 100 + 0.5) / 100');
  if n = src then raise exception 'round_act: rps nao encontrado'; end if; execute n;
end $m$;
